const sound_bank_clip_t kSoundBank[] = {
    {"angry", k_pcm_angry, 14400},
    {"curious", k_pcm_curious, 14400},
    {"defiant", k_pcm_defiant, 14400},
    {"devastated", k_pcm_devastated, 14400},
    {"excited", k_pcm_excited, 14400},
    {"impatient", k_pcm_impatient, 14400},
    {"laugh", k_pcm_laugh, 14400},
    {"mmh", k_pcm_mmh, 14400},
    {"mock", k_pcm_mock, 14400},
    {"no", k_pcm_no, 14400},
    {"sad", k_pcm_sad, 14400},
    {"yes", k_pcm_yes, 12800},
    {"yes_fast", k_pcm_yes_fast, 10880},
};
const size_t kSoundBankCount = 13;

const sound_bank_clip_t *sound_bank_find(const char *tag)
{
    if (!tag) return NULL;
    for (size_t i = 0; i < kSoundBankCount; ++i) {
        if (strcmp(kSoundBank[i].tag, tag) == 0) return &kSoundBank[i];
    }
    return NULL;
}
